// Package server maps HTTP requests onto the key/value API.
package server

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strconv"
	"strings"

	"kvhttp/internal/store"
)

const (
	// MaxValueBytes is the largest accepted value (request body) size.
	MaxValueBytes = 1 << 20
	// maxDrainBytes bounds how much of a rejected body is discarded before
	// replying, so the client sees the response instead of a reset.
	maxDrainBytes = 64 << 20

	maxKeyLength = 64
	kvPrefix     = "/kv/"
)

// Handler serves the key/value API backed by a Store.
type Handler struct {
	store *store.Store
}

// New returns a Handler backed by s.
func New(s *store.Store) *Handler {
	return &Handler{store: s}
}

// ValidKey reports whether key matches [A-Za-z0-9_-]{1,64}.
func ValidKey(key string) bool {
	if len(key) == 0 || len(key) > maxKeyLength {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

func (h *Handler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// Route on the raw request target so percent-encoded or otherwise
	// non-canonical paths are judged exactly as sent.
	path := r.RequestURI

	switch {
	case path == "/health":
		if r.Method != http.MethodGet {
			writeStatus(w, http.StatusMethodNotAllowed)
			return
		}
		writeBody(w, http.StatusOK, "text/plain; charset=utf-8", []byte("ok"))
	case path == "/kv":
		if r.Method != http.MethodGet {
			writeStatus(w, http.StatusMethodNotAllowed)
			return
		}
		body, err := json.Marshal(h.store.Keys())
		if err != nil {
			log.Printf("kvhttp: encoding key list: %v", err)
			writeStatus(w, http.StatusInternalServerError)
			return
		}
		writeBody(w, http.StatusOK, "application/json", body)
	case strings.HasPrefix(path, kvPrefix):
		key := path[len(kvPrefix):]
		if !ValidKey(key) {
			writeStatus(w, http.StatusBadRequest)
			return
		}
		h.serveKey(w, r, key)
	default:
		writeStatus(w, http.StatusNotFound)
	}
}

func (h *Handler) serveKey(w http.ResponseWriter, r *http.Request, key string) {
	switch r.Method {
	case http.MethodGet:
		value, ok := h.store.Get(key)
		if !ok {
			writeStatus(w, http.StatusNotFound)
			return
		}
		writeBody(w, http.StatusOK, "application/octet-stream", value)
	case http.MethodPut:
		value, err := readValue(r)
		if err != nil {
			var tooLarge *http.MaxBytesError
			if errors.As(err, &tooLarge) {
				drain(r.Body)
				writeStatus(w, http.StatusRequestEntityTooLarge)
				return
			}
			writeStatus(w, http.StatusBadRequest)
			return
		}
		if h.store.Put(key, value) {
			writeStatus(w, http.StatusCreated)
		} else {
			writeStatus(w, http.StatusOK)
		}
	case http.MethodDelete:
		if h.store.Delete(key) {
			writeStatus(w, http.StatusNoContent)
		} else {
			writeStatus(w, http.StatusNotFound)
		}
	default:
		writeStatus(w, http.StatusMethodNotAllowed)
	}
}

// readValue reads the request body, enforcing MaxValueBytes.
func readValue(r *http.Request) ([]byte, error) {
	if r.ContentLength > MaxValueBytes {
		return nil, &http.MaxBytesError{Limit: MaxValueBytes}
	}
	body := http.MaxBytesReader(nil, r.Body, MaxValueBytes)
	if r.ContentLength > 0 {
		buf := make([]byte, r.ContentLength)
		if _, err := io.ReadFull(body, buf); err != nil {
			return nil, err
		}
		return buf, nil
	}
	return io.ReadAll(body)
}

// drain discards up to maxDrainBytes of unread body.
func drain(body io.Reader) {
	_, _ = io.CopyN(io.Discard, body, maxDrainBytes)
}

func writeStatus(w http.ResponseWriter, status int) {
	if status == http.StatusNoContent {
		w.WriteHeader(status)
		return
	}
	writeBody(w, status, "", nil)
}

func writeBody(w http.ResponseWriter, status int, contentType string, body []byte) {
	hdr := w.Header()
	if contentType != "" {
		hdr.Set("Content-Type", contentType)
	}
	hdr.Set("Content-Length", strconv.Itoa(len(body)))
	w.WriteHeader(status)
	if len(body) > 0 {
		if _, err := w.Write(body); err != nil {
			log.Printf("kvhttp: writing response: %v", err)
		}
	}
}

package server

import (
	"bytes"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"kvhttp/internal/store"
)

func do(t *testing.T, h http.Handler, method, target string, body []byte) *http.Response {
	t.Helper()
	var r io.Reader
	if body != nil {
		r = bytes.NewReader(body)
	}
	req := httptest.NewRequest(method, target, r)
	rec := httptest.NewRecorder()
	h.ServeHTTP(rec, req)
	return rec.Result()
}

func TestRoutes(t *testing.T) {
	h := New(store.New())
	steps := []struct {
		method, target string
		body           string
		wantStatus     int
		wantBody       string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/kv", "", 200, "[]"},
		{"PUT", "/kv/b", "2", 201, ""},
		{"PUT", "/kv/a", "1", 201, ""},
		{"PUT", "/kv/a", "one", 200, ""},
		{"GET", "/kv/a", "", 200, "one"},
		{"GET", "/kv", "", 200, `["a","b"]`},
		{"PATCH", "/kv/a", "", 405, ""},
		{"DELETE", "/kv/a", "", 204, ""},
		{"DELETE", "/kv/a", "", 404, ""},
		{"GET", "/kv/a", "", 404, ""},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/a.b", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/%41", "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("k", 65), "", 400, ""},
		{"GET", "/nope", "", 404, ""},
	}
	for _, s := range steps {
		resp := do(t, h, s.method, s.target, []byte(s.body))
		got, _ := io.ReadAll(resp.Body)
		if resp.StatusCode != s.wantStatus || string(got) != s.wantBody {
			t.Errorf("%s %s: got %d %q, want %d %q", s.method, s.target, resp.StatusCode, got, s.wantStatus, s.wantBody)
		}
	}
}

func TestValueLimit(t *testing.T) {
	h := New(store.New())
	if resp := do(t, h, "PUT", "/kv/max", make([]byte, MaxValueBytes)); resp.StatusCode != 201 {
		t.Errorf("1 MiB value: status %d, want 201", resp.StatusCode)
	}
	if resp := do(t, h, "PUT", "/kv/over", make([]byte, MaxValueBytes+1)); resp.StatusCode != 413 {
		t.Errorf("oversized value: status %d, want 413", resp.StatusCode)
	}
}

// Package store provides a concurrency-safe in-memory key/value store.
package store

import (
	"slices"
	"sync"
)

// Store is a thread-safe in-memory key/value store. Stored values are treated
// as immutable: callers must not modify a slice after passing it to Put or
// after receiving it from Get.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// New returns an empty Store.
func New() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Put stores value under key. It reports whether the key was newly created.
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, exists := s.data[key]
	s.data[key] = value
	return !exists
}

// Get returns the value stored under key and whether it was present.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.data[key]
	delete(s.data, key)
	return ok
}

// Keys returns every key in ascending byte order. The result is never nil.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.data))
	for k := range s.data {
		keys = append(keys, k)
	}
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

// Command app is an in-memory HTTP/1.1 key/value server.
//
// Usage: app <port>
package main

import (
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"strconv"
	"time"

	"kvhttp/internal/server"
	"kvhttp/internal/store"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintf(os.Stderr, "usage: %s <port>\n", os.Args[0])
		os.Exit(2)
	}
	port, err := strconv.ParseUint(os.Args[1], 10, 16)
	if err != nil || port == 0 {
		fmt.Fprintf(os.Stderr, "kvhttp: invalid port %q\n", os.Args[1])
		os.Exit(2)
	}

	addr := net.JoinHostPort("127.0.0.1", strconv.FormatUint(port, 10))
	ln, err := net.Listen("tcp", addr)
	if err != nil {
		log.Fatalf("kvhttp: listen: %v", err)
	}

	srv := &http.Server{
		Handler:           server.New(store.New()),
		ReadHeaderTimeout: 30 * time.Second,
		ReadTimeout:       30 * time.Second,
		WriteTimeout:      30 * time.Second,
		IdleTimeout:       30 * time.Second,
		MaxHeaderBytes:    64 << 10,
	}
	log.Fatal(srv.Serve(ln))
}
